const env = { base_location: base, lang: 'en_US', timezone: 'Asia/Shanghai', user_agent: 'n8n-sku-updater/1.0' };
const helpers = this.helpers;

async function rpc(service, method, args) {
  const res = await helpers.httpRequest({
    url: base + '/jsonrpc', method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { service: service, method: method, args: args } }),
    ignoreResponseCodeErrors: true
  });
  let body = res;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) {} }
  if (body && body.error) {
    const d = body.error.data || {};
    throw new Error(d.message || body.error.message || JSON.stringify(body.error));
  }
  return body ? body.result : null;
}

const uid = await rpc('common', 'authenticate', [db, login, password, env]);

async function callKw(model, method, args, kwargs) {
  return rpc('object', 'execute_kw', [db, uid, password, model, method, args, kwargs || {}]);
}

const items = $input.all();
const upcSet = {};
for (const it of items) { const u = it.json.upc; if (u) upcSet[u] = true; }
const upcs = Object.keys(upcSet);
const prodMap = {};
for (let s = 0; s < upcs.length; s += 500) {
  const slice = upcs.slice(s, s + 500);
  const rows = await callKw('product.product', 'search_read', [], { domain: [['default_code', 'in', slice]], fields: ['id', 'default_code'] });
  for (const r of rows) {
    const c = String(r.default_code || '').trim();
    if (!c) continue;
    if (!prodMap[c]) prodMap[c] = [];
    prodMap[c].push({ id: r.id });
  }
}
const ids = [];
for (const k in prodMap) { for (const p of prodMap[k]) ids.push(p.id); }
const packsByProduct = {};
for (let s = 0; s < ids.length; s += 500) {
  const slice = ids.slice(s, s + 500);
  const rows = await callKw('product.packaging', 'search_read', [], { domain: [['product_id', 'in', slice]], fields: ['id', 'name', 'qty', 'product_id'] });
  for (const r of rows) {
    const pid = (r.product_id && r.product_id.length) ? r.product_id[0] : null;
    if (!pid) continue;
    if (!packsByProduct[pid]) packsByProduct[pid] = [];
    packsByProduct[pid].push({ id: r.id, name: r.name || '', qty: r.qty });
  }
}
const out = [];
for (const it of items) {
  const j = it.json;
  const list = prodMap[j.upc] || null;
  const productIds = list ? list.map(function (p) { return p.id; }) : [];
  let packs = [];
  if (productIds.length === 1) packs = packsByProduct[productIds[0]] || [];
  out.push({ json: { fileName: j.fileName, upc: j.upc, mode: j.mode, packN: j.packN, sku: j.sku, brand: j.brand, country: j.country, productIds: productIds, packs: packs } });
}
return out;

const items = $input.all();
const skuWrites = [];
const productWrites = [];
const stats = { total: 0, notfound: 0, dup: 0, noSku: 0, noPack: 0, skuWrite: 0, productWrite: 0 };
const fileNames = {};
for (const it of items) {
  const r = it.json;
  stats.total++;
  if (r.fileName) fileNames[r.fileName] = true;
  if (!r.productIds || r.productIds.length === 0) { stats.notfound++; continue; }
  if (r.productIds.length > 1) { stats.dup++; continue; }
  const pid = r.productIds[0];
  const vals = {};
  if (r.brand) vals.brand = r.brand;
  if (r.country) vals.origin_country = r.country;
  if (Object.keys(vals).length) { productWrites.push({ id: pid, upc: r.upc, vals: vals }); stats.productWrite++; }
  if (r.sku) {
    if (r.mode === 'single') {
      const p = (r.packs || []).find(function (pk) { return Number(pk.qty) === 1; });
      if (p) { skuWrites.push({ id: p.id, upc: r.upc, sku: r.sku, field: 'single_sku', spec: p.name }); stats.skuWrite++; }
      else { stats.noPack++; }
    } else {
      const N = r.packN;
      const p = (r.packs || []).find(function (pk) { const mm = (pk.name || '').match(/1 box of (\d+) pieces/i); return mm && parseInt(mm[1], 10) === N; })
        || (r.packs || []).find(function (pk) { return Number(pk.qty) === N; });
      if (p) { skuWrites.push({ id: p.id, upc: r.upc, sku: r.sku, field: 'box_sku', spec: p.name }); stats.skuWrite++; }
      else { stats.noPack++; }
    }
  } else { stats.noSku++; }
}
return [{ json: { skuWrites: skuWrites, productWrites: productWrites, stats: stats, fileNames: Object.keys(fileNames) } }];

